"""Isolated Step 2 for the clean path (PRD §5): search the entity's stored evidence for each {thesis, incoming evidence} association,
ask Jev how the incoming evidence relates to each candidate, and turn the answers into the outcome Step 3 writes.

Search: one query per association (the thesis question, then the incoming summary and passages) against each group's original record
(summary, passages, party, statement date, period), cosine similarity of embeddings, top 10; a record with no association, or one that
lists the company's figures (a condition), also gets one entity-wide query of its own text (STEP1-CONDITIONS-DESIGN.md §10.1); the union
of the results is compared. The figures never enter a search or comparison text, so a wrongly paired figure cannot change Step 2 (§14);
the comparison reads the full passages (§15). Comparison: Jev's piece question with the production criteria (views/jev_matching), the incoming piece as state, one question
per candidate. Outcome: any same_statement makes the record a repeat of the candidate with the highest same_statement probability, ties
going to the earliest group (Alex, 2026-11-08: only the group it is most like); a supersedes answer on another candidate becomes a
revision link; with no same_statement, supersedes answers make it a revision of those groups; otherwise it is new.

`forward` runs articles in order against the library as it stood after the previous article: records of one article never see each
other. A failed comparison is refused by the library, reported, and the run continues."""
import concurrent.futures
import math
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'src'))
from hivemind.views import jev_matching  # noqa: E402

TOP = 10


def stated(record):
    return record['statement_date'] or record.get('statement_date_text') or 'unknown'


def doc_text(record):
    return '\n'.join([record['summary'], ' '.join(record['passages']), f"party: {record['original_party'] or 'unknown'}",
                      f"stated: {stated(record)}", f"period: {record['evidence_period'] or 'unknown'}"])


def query_text(record, thesis_question):
    return f"thesis: {thesis_question}\n{record['summary']}\n{' '.join(record['passages'])}"


def piece_text(record, label):
    return (f"{label} [{record['tier']}; {record['reporting_speaker']}; original source {record['original_party']}, stated "
            f"{stated(record)}] {record['summary']} | quote: {' '.join(record['passages'])}")


def query_vectors(vectors, record, thesis_questions):
    """The search queries of one record, in order: one per thesis association, then its own text when it has no association or lists
    the company's figures."""
    queries = [vectors[query_text(record, thesis_questions[t])] for t in record['thesis_ids']]
    if not record['thesis_ids'] or record.get('figures'):
        queries.append(vectors[doc_text(record)])
    return queries


# Jev's piece criteria aligned with the Step 2 merge line's own test (PRD §5 line 2; AGENTS §7.1, one ruler): a repeat is a later report
# of the stored piece's main statement. Production's wording (views/jev_matching.PIECES) judged "the same evidence", so a later report of
# only a secondary statement inside a stored record (an official's denial carried in the report it denies) was merged as a repeat.
PIECES = {'same_statement': "the INCOMING PIECE reports the STORED PIECE's main statement: a retelling, another outlet carrying it, the "
                            "same number in text or a table, or the same speaker repeating it; wording, precision and extra detail may "
                            "differ. If the stored piece carries several statements and the incoming piece reports only a secondary one, "
                            "this is not it",
          'supersedes': "a later version of the stored piece's main statement, changed: the same speaker revises that guidance, "
                        "forecast or event-progress statement, an official confirms or denies that reported claim, or the original "
                        "source revises it; another statement on the same topic is not this",
          'different': "a different fact, figure or matter, a figure for another period or quantity, or only a secondary statement of "
                       "the stored piece, even if on the same topic"}


def piece_question(text):
    return {'type': 'choice', 'criteria': PIECES,
            'instructions': 'How does the INCOMING PIECE relate to the STORED PIECE below? Use only the supplied text. STORED PIECE:\n' + text}


INFORMS = {'true': "the STORED PIECE bears on the THESIS's own matter (the parties, products, policy or quantity the THESIS names) and "
                   "makes its answer more or less likely, as evidence filed under it would",
           'false': "the STORED PIECE concerns another matter, or is a company-wide result or event that does not speak to the THESIS's "
                    "own matter, or would not change its answer"}


def informs_question(text):
    return {'type': 'noul', 'criteria': INFORMS,
            'instructions': 'Does the STORED PIECE below inform the THESIS stated above? Use only the supplied text; a shared company, '
                            'product family or word is not enough, and the company\'s overall results, guidance and estimates inform a '
                            'thesis about its revenue or earnings path, not one about a competitor, a supplier or a policy unless they '
                            'speak to it. STORED PIECE:\n' + text}


def later_link_judge(library, thesis_question, ask):
    """The judge `Library.link_later` calls: one Jev request per batch, the thesis as state, one yes/no question per stored group."""
    def judge(group_ids):
        questions = {f'q{i}': informs_question(piece_text(library.groups[g]['original'], 'STORED PIECE')) for i, g in enumerate(group_ids)}
        raw = ask(f'THESIS: {thesis_question}', questions)
        return {g: raw[f'q{i}']['noul'] >= jev_matching.THRESHOLD for i, g in enumerate(group_ids)}
    return judge


def cosine(a, b):
    return sum(x * y for x, y in zip(a, b)) / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)) or 1)


def search(library, vectors, record, thesis_questions):
    """Candidate group ids: each query's top 10 by cosine against the groups' original records, merged in rank order."""
    candidates = []
    for query in query_vectors(vectors, record, thesis_questions):
        ranked = sorted(library.order, key=lambda g: -cosine(query, vectors[doc_text(library.groups[g]['original'])]))[:TOP]
        candidates += [g for g in ranked if g not in candidates]
    return candidates


def outcome(answers, order):
    """answers: {group id: {'choice', 'probabilities'}}; order: group ids in creation order."""
    same = [g for g, a in answers.items() if a['choice'] == 'same_statement']
    later = [g for g, a in answers.items() if a['choice'] == 'supersedes']
    if same:
        best = max(same, key=lambda g: (answers[g]['probabilities']['same_statement'], -order.index(g)))
        return {'kind': 'repeat', 'repeat_of': [best], 'revises': later}
    if later:
        return {'kind': 'revision', 'revises': later}
    return {'kind': 'new'}


def forward(articles, library, vectors, thesis_questions, ask, workers=8, opened=None):
    """articles: lists of Step 3 records in article order. ask(state, questions) returns Jev's answers by question id, or raises.
    opened: per article, the thesis ids it opened; after the article's records are written, each is linked later to the stored groups
    that arrived unlinked from earlier articles (`Library.link_later`). A thesis written to with pairs still pending is judged again,
    against its opening boundary. Returns one decision per record."""
    decisions = []
    for index, records in enumerate(articles):
        def decide(record):
            candidates = search(library, vectors, record, thesis_questions)
            if not candidates:
                return record, candidates, {}, {'kind': 'new'}
            questions = {f'q{i}': piece_question(piece_text(library.groups[g]['original'], 'STORED PIECE'))
                         for i, g in enumerate(candidates)}
            incoming = piece_text(record, 'INCOMING PIECE')
            try:
                raw = ask(incoming, questions)
            except Exception as first:   # retried once; a second failure is reported, never silently saved as new
                try:
                    raw = ask(incoming, questions)
                except Exception as error:
                    return record, candidates, {}, {'kind': 'failed', 'reason': f'{type(first).__name__}: {first}; retry: {type(error).__name__}: {error}'}
            answers = {g: {'choice': raw[f'q{i}']['choice'], 'probabilities': raw[f'q{i}']['probabilities']} for i, g in enumerate(candidates)}
            return record, candidates, answers, outcome(answers, library.order)
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
            results = list(pool.map(decide, records))
        for record, candidates, answers, result in results:
            entry = {'id': record['id'], 'candidates': candidates, 'answers': answers, 'outcome': result}
            try:
                entry['group'] = library.apply(record, result)
            except Exception as error:
                entry['refused'] = f'{type(error).__name__}: {error}'
            decisions.append(entry)
        article = records[0]['article'] if records else None
        if article is None:
            continue
        written = {t for r in records for t in r['thesis_ids']}
        retry = [t for t in written if t in library.pending and t not in (opened[index] if opened else [])]
        for thesis_id in list(opened[index] if opened else []) + retry:   # opened here, or written to with pairs still pending
            result = library.link_later(thesis_id, later_link_judge(library, thesis_questions[thesis_id], ask), article)
            library.later_log.append({'thesis': thesis_id, 'article': article, **result})
    return decisions

"""Isolated Step 3 evidence library for the clean path (PRD §6): an in-memory logical store and its dossier text, not the live writer.

A group is one stored statement. Its original record keeps its id and fields unchanged and gives the group its id. A later record that
Step 2 judged a repeat joins the group as a member and keeps its own id, text, fields and source article. Thesis links belong to the
group and remember the record that brought each one. A revision is its own group, linked to every group it revises; a repeat that also
revises another group adds that link to its own group, naming the member that established it.

The writer refuses rather than guesses: a failed comparison, several repeat targets, an unknown group, or a replayed record whose
placement differs from the first time raise `Refused` and write nothing. Physical storage and crash recovery are not provided here.

Later linking (Alex, 2026-11-08: a material statement no thesis takes is kept and linked when a related thesis opens; design
STEP1-CONDITIONS-DESIGN.md §§11.1, 17): when a thesis opens, every group whose original arrived with no link, from an earlier article,
is judged against it in batches. Each judged (thesis, group) pair is recorded once in `judged`; a batch that fails twice stays pending,
is reported, and is judged again on the next write to that thesis, against the same opening boundary (`opened_at`)."""
import copy

RECORD_FIELDS = ('id', 'article', 'publisher', 'publication_date', 'summary', 'passages', 'original_party', 'reporting_speaker', 'tier',
                 'statement_date', 'evidence_period', 'thesis_ids')


class Refused(Exception):
    """A Step 2 outcome the library will not write; nothing was changed."""


class Library:
    def __init__(self):
        self.groups = {}       # group id → {'original': record, 'members': [record], 'links': {thesis id: record id}, 'revises': [{'group', 'by'}]}
        self.placement = {}    # record id → group id
        self.order = []        # group ids in the order they were created
        self.judged = {}       # (thesis id, group id) → True | False, the later-linking ledger
        self.later_log = []    # one entry per later-linking call: thesis, article, linked, pending, judged
        self.opened_at = {}    # thesis id → the article that opened it: the boundary of its later linking
        self.pending = {}      # thesis id → group ids whose judgement failed twice and waits for the next write to the thesis

    def apply(self, record, outcome):
        """Write one record with its Step 2 outcome: {'kind': 'new' | 'repeat' | 'revision' | 'failed', 'repeat_of': [group ids],
        'revises': [group ids], 'reason': text}. Returns the id of the group that holds the record."""
        missing = [f for f in RECORD_FIELDS if f not in record]
        if missing:
            raise Refused(f'record lacks {missing}')
        kind, repeat_of, revises = outcome['kind'], list(outcome.get('repeat_of') or []), list(outcome.get('revises') or [])
        if kind == 'failed':
            raise Refused(f"comparison failed for {record['id']}: {outcome.get('reason', 'no reason given')}")
        if kind not in ('new', 'repeat', 'revision'):
            raise Refused(f'unknown outcome {kind!r}')
        if (kind == 'repeat') != bool(repeat_of) or len(repeat_of) > 1:
            raise Refused(f"a repeat names exactly one group; got {repeat_of} for outcome {kind}")
        if kind == 'revision' and not revises:
            raise Refused('a revision names the group it revises')
        for group_id in repeat_of + revises:
            if group_id not in self.groups:
                raise Refused(f'unknown group {group_id}')
        target = repeat_of[0] if repeat_of else record['id']
        if record['id'] in self.placement:
            if self.placement[record['id']] != target:
                raise Refused(f"{record['id']} was placed in {self.placement[record['id']]}, not {target}")
            group = self.groups[target]
            stored = next(r for r in [group['original']] + group['members'] if r['id'] == record['id'])
            if {k: v for k, v in stored.items() if k != 'thesis_ids'} != {k: v for k, v in record.items() if k != 'thesis_ids'}:
                raise Refused(f"{record['id']} names a stored record with different content; a changed record needs a new id")
            self._link(group, record)
            return target
        if kind == 'repeat':
            group = self.groups[target]
            group['members'].append(copy.deepcopy(record))
        else:
            group = {'original': copy.deepcopy(record), 'members': [], 'links': {}, 'revises': []}
            self.groups[target] = group
            self.order.append(target)
        self.placement[record['id']] = target
        self._link(group, record)
        for revised in revises:
            if revised != target and not any(r['group'] == revised for r in group['revises']):
                group['revises'].append({'group': revised, 'by': record['id']})
        return target

    def link_later(self, thesis_id, judge, before_article, batch=10):
        """Judge every group whose original arrived unlinked from an article before `before_article` against a newly opened thesis.
        judge(group ids) returns {group id: True | False} or raises. Returns {'linked': [...], 'pending': [...], 'judged': n}."""
        self.opened_at.setdefault(thesis_id, before_article)
        before_article = self.opened_at[thesis_id]
        todo = [g for g in self.order if not self.groups[g]['original']['thesis_ids']
                and self.groups[g]['original']['article'] < before_article and (thesis_id, g) not in self.judged]
        linked, pending = [], []
        for start in range(0, len(todo), batch):
            ids = todo[start:start + batch]
            answers = None
            for _attempt in range(2):
                try:
                    answers = judge(ids)
                    break
                except Exception:   # tried twice, then reported as pending, never saved as a judgement
                    answers = None
            if answers is None:
                pending += ids
                continue
            for group_id in ids:
                self.judged[(thesis_id, group_id)] = bool(answers[group_id])
                if answers[group_id]:
                    self.groups[group_id]['links'].setdefault(thesis_id, self.groups[group_id]['original']['id'])
                    linked.append(group_id)
        if pending:
            self.pending[thesis_id] = pending
        else:
            self.pending.pop(thesis_id, None)
        return {'linked': linked, 'pending': pending, 'judged': len(todo) - len(pending)}

    @staticmethod
    def _link(group, record):
        for thesis_id in record['thesis_ids']:
            group['links'].setdefault(thesis_id, record['id'])

    @staticmethod
    def articles(group):
        """Distinct source articles of a group, oldest first; two records from one article count once."""
        seen = []
        for record in [group['original']] + group['members']:
            if record['article'] not in seen:
                seen.append(record['article'])
        return seen

    def dossier(self, thesis_id):
        """Group ids linked to a thesis, in creation order."""
        return [g for g in self.order if thesis_id in self.groups[g]['links']]


def labelled_passages(record):
    """Each passage as a reader sees it: the source text Step 1 found, labelled 'Quote', or, when Step 1 did not find it (verified
    value None), the model's text labelled 'Unverified quote'. The model's own text stays in the record's `passages`. A record stored
    before verification was carried shows its passages as 'Quote'."""
    verified = record.get('verified_passages') or record['passages']
    return [('Quote', found) if found is not None else ('Unverified quote', passage) for passage, found in zip(record['passages'], verified)]


def record_text(record, label):
    attribution = record['original_party'] or 'unknown party'
    if record['reporting_speaker'] and record['reporting_speaker'] != record['original_party']:
        attribution += f", reported by {record['reporting_speaker']}"
    head = (f"[{label}] {record['publication_date']} · {record['publisher'] or 'unknown publisher'} · {attribution} · tier {record['tier']}"
            f" · stated {record['statement_date'] or 'unknown'} · period {record['evidence_period'] or 'unknown'}")
    quotes = '\n'.join(f'  {label_of}: "{p}"' for label_of, p in labelled_passages(record))
    return f"{head}\n  {record['summary']}\n{quotes}"


def group_text(library, group_id, label, labels, member_text=True, notes=()):
    """A group as a reader sees it: the original record, then each later report of the same statement in arrival order, with its own
    text when `member_text` is set and as a source line otherwise. Distinct articles are counted; repeats are not called confirmation."""
    group = library.groups[group_id]
    lines = [record_text(group['original'], label)]
    if group['members']:
        articles = library.articles(group)
        publishers = {r['publisher'] for r in [group['original']] + group['members']}
        lines.append(f'  Later reports of the same statement: {len(group["members"])} records from {len(articles) - 1} further articles '
                     f'({len(publishers)} publishers in all). Articles repeating a statement do not by themselves confirm it independently.')
        for member in group['members']:
            if member_text:
                party = '' if member['original_party'] == group['original']['original_party'] else f" · {member['original_party']}"
                quotes = ' '.join(f'"{p}"' if kind == 'Quote' else f'"{p}" (unverified)' for kind, p in labelled_passages(member))
                lines.append(f"    - {member['publication_date']} · {member['publisher']}{party}: {member['summary']}\n      Quote: {quotes}")
            else:
                lines.append(f"    - {member['publication_date']} · {member['publisher']}")
    for revised in group['revises']:
        lines.append(f"  Revises [{labels[revised['group']]}]." if revised['group'] in labels else '  Revises an entry outside this dossier.')
    lines += [f'  {note}' for note in notes]
    return '\n'.join(lines)

"""The matching step answered by Jev instead of a generative call (log row 34). For each candidate: its relation to every
thesis on its list (one `choice` per thesis) and its membership of every visible research group (one `noul` per group);
for each incoming piece of evidence: its relation to every stored piece on its list under each linked thesis (one
`choice` per stored piece). Code turns the probabilities into an answer in the matching schema, so `matching.check` and
`writing.write` run unchanged: `merge` when a listed open thesis is the same quantity or event, `succession` when a
listed thesis carries the same key for an earlier period and has no successor, else `new`; `repeat` when a stored
piece is the same statement, `replace` when the incoming piece supersedes it, else `new`. Dependencies are not asked.
Thresholds are pre-set (0.5); a membership above the threshold is added to the candidate's group references."""
import dataclasses
import hashlib
import concurrent.futures
import copy

from .. import config, jev, model, universe as _universe
from . import identity, matching, store

THRESHOLD = 0.5
# D190: the collision judge. Jev reads wording and calls a population variant of one aggregate 'part of' (six 2026 aggregates on the r3
# ledger, each judged 'new'); the generative model, asked the analyst's question, merged five of six. It is asked only for the theses of
# the candidate's own object and measure, and its verdict on those replaces Jev's.
COLLISION_RELATIONS = ['same_question', 'same_question_other_period', 'distinct_question_same_matter', 'different']
COLLISION_SCHEMA = {'type': 'object', 'additionalProperties': False, 'required': ['relations'],
                    'properties': {'relations': {'type': 'array', 'items': {'type': 'object', 'additionalProperties': False, 'required': ['thesis_id', 'relation', 'why'],
                                   'properties': {'thesis_id': {'type': 'string'}, 'relation': {'type': 'string', 'enum': COLLISION_RELATIONS}, 'why': {'type': 'string'}}}}}}
RELATIONS = {"same_quantity_or_event": "both ask about the same defined quantity or the same event: alternative wordings, or two estimates or figures of that one quantity",
             "same_quantity_other_period": "the same defined quantity or event series for another period, such as the next fiscal or calendar year",
             "part_of": "one asks about a strict component or subset of the other, in either direction; not identical",
             "same_matter_different_quantity": "one ongoing matter, two distinct quantities or events, neither a component of the other",
             "different": "different matters; sharing a company or industry is not enough",
             "cannot_tell": "the supplied material is insufficient or inconsistent"}
MEMBER_CRITERIA = {"true": "the CANDIDATE tracks this matter, one of its stated components, its implementation, or a deployment the supplied material connects to it",
                   "false": "the supplied material shows a different matter, or a question outside the GROUP's stated scope"}
# 06-views.md, the evidence table: repeat = "the same evidence already exists under the thesis: a retelling, the same number in text and
# table, or the same speaker repeating the same statement"; replace = "a later account of the same matter: a speaker revises guidance,
# forecast or event progress; an official confirms/denies a rumour; or the original source revises its statement". The criteria carry
# those words; the first seed run (log row 35) read "same occasion" into them and missed six cross-document repeats.
PIECES = {"same_statement": "the same evidence: a retelling, the same number stated in text and in a table or in another document, or the same speaker repeating the same statement; wording, precision and document may differ",
          "supersedes": "a later version of the same statement or number, changed: the same speaker revises that guidance, forecast or event-progress statement, an official confirms or denies that reported claim, or the original source revises that statement; another statement on the same topic is not this",
          "different": "a different fact, figure or matter, or a figure for another period or quantity, even if on the same topic"}


@dataclasses.dataclass
class Decision:
    data: dict
    call_id: int
    request_sha256: str
    cached: bool
    prompt_chars: int
    input_tokens: int
    output_tokens: int
    cost_usd: float
    calls: int = 0
    request_records: list = dataclasses.field(default_factory=list)


def candidate_state(c, evidence):
    rungs = ' / '.join(f'{r["label"]}: {r["condition"]}' for r in c['rungs'])
    fields = ', '.join(f'{f}={c[f]}' for f in ('measure', 'scope', 'period_start', 'period_end', 'basis', 'unit', 'event_type') if c.get(f) not in (None, '', 'n/a'))
    own = ' | '.join(f'[{e["speaker"]} {e["original_day"]}] {e["quote"][:400]}' for e in evidence if e['id'] in c.get('evidence_ids', []))[:1600]
    return (f'CANDIDATE ({c["kind"]}, object {c["object"]}, focus "{c["looks_at"]}", {c["year"]}, due {c["due_day"]}): {c["question"]}\n'
            f'Key: {fields}\nLadder: {rungs}\nIts evidence: {own}')


def thesis_text(conn, view_id):
    """The thesis as the judge should see it: the card and the quotes that define it (its first two pieces in force)."""
    pieces = store.evidence_in_force(conn, view_id)[:2]
    quotes = ''.join(f'\n    Evidence: [{p["speaker"]} {p["original_day"]}] {p["quote"][:400]}' for p in pieces)
    return matching.describe_view(conn, view_id, english=True) + quotes


def group_text(group):
    members = '; '.join(m['looks_at'] for m in group.get('members', []))
    return f'{group["name"]}. Scope: {group["scope"]} Also called: {", ".join(group.get("aliases") or [])}. Member questions: {members or "(none yet)"}'


def piece_state(e, said_day):
    return f'INCOMING PIECE [{e["tier"]}; {e["speaker"]}; original source {e["original_who"]}, stated {said_day}] {e["one_line"]} | quote: {e["quote"][:600]}'


def relation_question(text):
    return {'type': 'choice', 'criteria': RELATIONS,
            'instructions': 'What relationship holds between the CANDIDATE and the THESIS below? Use only the supplied text. Equal numbers and similar wording do not establish identity. THESIS:\n' + text}


def member_question(text):
    return {'type': 'noul', 'criteria': MEMBER_CRITERIA,
            'instructions': 'Does the CANDIDATE belong to the ongoing matter defined by GROUP below? Use only the supplied text; a shared company, industry or word is not enough. GROUP:\n' + text}


def piece_question(text):
    return {'type': 'choice', 'criteria': PIECES,
            'instructions': 'How does the INCOMING PIECE relate to the STORED PIECE below, already under the same thesis? Use only the supplied text. STORED PIECE:\n' + text}


def event_home(conn, view_id, key, c):
    """D248 item 2 (R2-a): an open event question of the same object takes the same event under another deadline; the deadline is
    evidence, and the successor opens only once the question has closed (can_succeed)."""
    return bool(key) and key.get('measure') in identity.EVENT_MEASURES and store.is_open(conn, view_id) \
        and (store.view(conn, view_id) or {}).get('object_id') == c.get('object') and not identity.conflicts(key, c, merging=False)


def can_succeed(conn, view_id, key, c):
    """06-views succession: the candidate asks the same object's quantity (no typed field conflicts: measure, event type, a stated
    basis or unit, a code-owned scope) for a later period that does not overlap, and the thesis has no successor yet."""
    return bool(key) and (store.view(conn, view_id) or {}).get('object_id') == c['object'] \
        and not identity.conflicts(key, c, merging=False) \
        and bool(key.get('period_end') and c.get('period_start') and key['period_end'] < c['period_start']) \
        and not conn.execute('select 1 from successions where succeeds=?', (view_id,)).fetchone()


def shared_quantity_target(conn, c):
    """D197: a shared quantity's destination is code's. An open thesis of the same theme, measure and period is the same
    thesis (merge); the latest earlier period without a successor is its predecessor (succession); otherwise none."""
    if not identity.is_shared(c) or not c.get('period_start'):
        return None
    exact = store.exact_key_views(conn, c)
    if exact:
        return 'merge', exact[0]
    earlier = []
    for row in conn.execute('select k.view_id, k.period_end from view_keys k join views v using(view_id) where v.object_id=? and k.measure=? order by k.period_end desc',
                            (c['object'], c['measure'])):
        key = store.view_key(conn, row['view_id'])
        if key and identity.is_shared(key) and can_succeed(conn, row['view_id'], key, c):
            earlier.append(row['view_id'])
    return ('succession', earlier[0]) if earlier else None


def succession_target(conn, c, listed):
    """The succession code decides alone: the same scope as well (a model-worded scope that differs goes to the judge)."""
    if not c.get('measure') or not c.get('period_start'):
        return None
    for view_id in listed:
        key = store.view_key(conn, view_id)
        if key and _universe.scope_key(key.get('scope', '')) == _universe.scope_key(c.get('scope', '')) and can_succeed(conn, view_id, key, c):
            return view_id
    return None


def _summary(answer):
    if answer['type'] == 'noul':
        return f'{answer["noul"]:.2f}'
    top = max(answer['probabilities'].items(), key=lambda kv: kv[1])
    return f'{top[0]} {top[1]:.2f}'


def _answers(archive, cfg, jobs, workers, transport):
    """Ask independent questions; equal concurrent requests share one archived result."""
    if not isinstance(workers, int) or isinstance(workers, bool) or workers < 1:
        raise ValueError('Jev workers must be a positive integer')

    def ask(job):
        state, questions = job
        return jev.ask(archive, cfg, cfg.matching, state, questions, 'match', transport=transport)

    if workers == 1:
        return [ask(job) if job[1] else None for job in jobs]
    keys, unique, replies = [], {}, {}
    for state, questions in jobs:
        if not questions:
            keys.append(None)
            continue
        _, key = model.request_identity(jev.request_for(cfg.matching, state, questions))
        keys.append(key)
        if key not in unique:
            unique[key] = (state, copy.deepcopy(questions))
    waiting, active = iter(unique.items()), {}
    pool = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
    try:
        def fill():
            while len(active) < workers:
                next_job = next(waiting, None)
                if next_job is None:
                    break
                key, job = next_job
                active[pool.submit(ask, job)] = key
        fill()
        while active:
            concurrent.futures.wait(active, return_when=concurrent.futures.FIRST_COMPLETED)
            completed = [future for future in active if future.done()]
            # Check the whole completed set before submitting any replacement work.
            for future in completed:
                future.result()
            for future in completed:
                replies[active.pop(future)] = future.result()
            fill()
    finally:
        for future in active:
            future.cancel()
        pool.shutdown(wait=True, cancel_futures=True)
    results, used = [], set()
    for key in keys:
        if key is None:
            results.append(None)
            continue
        answer = replies[key]
        # A later logical use is exactly what a serial archive lookup would return.
        results.append(dataclasses.replace(answer, cached=True, cost_usd=0.0) if key in used else answer)
        used.add(key)
    return results


def collision_peers(conn, c, listed):
    """The listed theses of the candidate's own object and measure: where one question may be held twice under other words."""
    peers = []
    for v in listed:
        key = store.view_key(conn, v) if c.get('measure') else None
        if key and key.get('measure') == c.get('measure') and (store.view(conn, v) or {}).get('object_id') == c['object']:
            peers.append(v)
    return peers


def ask_collision_judge(archive, cfg, conn, state, peers, llm_transport):
    """One generative call: the candidate's state and the peers' thesis texts; returns {thesis_id: relation}."""
    with open(config.prompt_path(cfg.collision.prompt_version + '.txt'), encoding='utf-8') as handle:
        system = handle.read()
    user = state + '\n\nTHESES:\n' + '\n'.join(f'--- {v}\n{thesis_text(conn, v)}' for v in peers) + '\n\nFor each thesis id, state the relation.'
    answer = model.call(archive, cfg, cfg.collision, system, user, COLLISION_SCHEMA, 'collision', 'match', transport=llm_transport)
    return answer, {r['thesis_id']: r['relation'] for r in answer.data['relations'] if r['thesis_id'] in peers}


def decide(archive, cfg, conn, item, candidates, evidence, lists, shown_views, *, extra_views=(), retry_note='', transport=None, llm_transport=None, workers=1):
    data = {'candidates': [], 'evidence': []}
    total = Decision(data, 0, '', True, 0, 0, 0, 0.0)
    shas = []
    jobs, candidate_jobs, evidence_jobs = [], [], []
    # All database reads and request construction stay on the coordinator thread.
    for c in candidates:
        listed = list(dict.fromkeys(list(lists.candidate_lists.get(c['id'], [])) + [v['view_id'] for v in shown_views]))
        fixed = shared_quantity_target(conn, c)                       # D197: code decides a shared quantity's destination; Jev is not asked its relations
        questions = {} if fixed else {f'rel__{v}': relation_question(thesis_text(conn, v)) for v in listed}
        groups = store.groups_for_prompt(conn, [c['object']], f'{c["looks_at"]} {c["question"]}')
        for g in groups:
            questions[f'member__{g["group_id"]}'] = member_question(group_text(g))
        candidate_jobs.append((c, listed, groups, len(jobs) if questions else None, fixed))
        if questions:
            jobs.append((candidate_state(c, evidence), questions))
    for e in evidence:
        pairs = [(e['id'], v) for v in e['links'] if (e['id'], v) in lists.evidence_lists]
        if not pairs:
            continue
        questions = {f'piece__{v}__{x}': piece_question(matching.describe_evidence(conn, x, english=True)) for _, v in pairs for x in lists.evidence_lists[(e['id'], v)]}
        said_day = e.get('original_day') or item['publication_day']
        evidence_jobs.append((e, pairs, said_day, len(jobs)))
        jobs.append((piece_state(e, said_day), questions))
    replies = _answers(archive, cfg, jobs, workers, transport)

    def answers_for(index):
        answer = replies[index]
        if answer is None:
            return {}
        total.cost_usd += answer.cost_usd
        total.input_tokens += answer.input_tokens
        total.output_tokens += answer.output_tokens
        total.prompt_chars += answer.prompt_chars
        total.cached = total.cached and answer.cached
        total.call_id = answer.call_id
        total.calls += 1
        shas.append(answer.request_sha256)
        total.request_records.append({'call_id': answer.call_id, 'request_sha256': answer.request_sha256})
        return answer.data

    for c, listed, groups, job_index, fixed in candidate_jobs:
        answers = answers_for(job_index) if job_index is not None else {}
        joined = [g['group_id'] for g in groups if answers[f'member__{g["group_id"]}']['noul'] >= THRESHOLD]
        for group_id in joined:
            if group_id not in (c.get('group_refs') or []) and group_id not in (c.get('jev_group_refs') or []):
                c.setdefault('jev_group_refs', []).append(group_id)          # the writer records these with basis 'jev'
        if fixed:                                                # D197: one aggregate per theme, measure and period; the wording is not identity
            data['candidates'].append({'id': c['id'], 'outcome': fixed[0], 'target_view_id': fixed[1], 'dependencies': [],
                                       'reason': f'shared quantity: {fixed[0]} by key (D197); groups joined: {joined or "none"}'})
            continue
        same = sorted(((answers[f'rel__{v}']['probabilities']['same_quantity_or_event'], v) for v in listed
                       if answers[f'rel__{v}']['choice'] == 'same_quantity_or_event' and answers[f'rel__{v}']['probabilities']['same_quantity_or_event'] >= THRESHOLD),
                      reverse=True)
        reasons = '; '.join(f'{qid[5:]}: {_summary(a)}' for qid, a in answers.items() if qid.startswith('rel__'))
        outcome, target = 'new', ''
        for _, v in same:
            # the key decides what 'the same' may mean: a different quantity is declined here; the same quantity for a later period is a
            # succession (06-views), when the thesis has no successor yet; otherwise a merge into an open thesis
            key = store.view_key(conn, v) if c.get('measure') else None
            if key and identity.conflicts(key, c, merging=False):
                continue
            if key and identity.conflicts(key, c, merging=True):          # the same quantity for another period
                if can_succeed(conn, v, key, c):
                    outcome, target = 'succession', v
                    break
                continue
            if store.is_open(conn, v):
                outcome, target = 'merge', v
                break
        if outcome == 'new':
            # the judge says 'the same quantity for another period'; code decides the direction, the typed fields and the successor
            other = sorted(((answers[f'rel__{v}']['probabilities']['same_quantity_other_period'], v) for v in listed
                            if answers[f'rel__{v}']['choice'] == 'same_quantity_other_period' and answers[f'rel__{v}']['probabilities']['same_quantity_other_period'] >= THRESHOLD),
                           reverse=True)
            for _, v in other:
                key = store.view_key(conn, v) if c.get('measure') else None
                if event_home(conn, v, key, c):
                    outcome, target = 'merge', v
                    break
                if can_succeed(conn, v, key, c):
                    outcome, target = 'succession', v
                    break
        if outcome == 'new':
            # D258 (R2-e, D248 items 1 and 6): a candidate that asks about a component, instance or subset of an open question is filed
            # under it; the part is evidence of the card, not a card of its own. The typed fields still decide (a signing question never
            # merges into an amount), and the collision judge below may keep a component apart under its rule.
            parts = sorted(((answers[f'rel__{v}']['probabilities']['part_of'], v) for v in listed
                            if answers[f'rel__{v}']['choice'] == 'part_of' and answers[f'rel__{v}']['probabilities']['part_of'] >= THRESHOLD),
                           reverse=True)
            for _, v in parts:
                key = store.view_key(conn, v) if c.get('measure') else None
                if key and identity.conflicts(key, c, merging=False):
                    continue
                if store.is_open(conn, v):
                    outcome, target = 'merge', v
                    break
        if outcome == 'new':
            successor_of = succession_target(conn, c, listed)
            if successor_of:
                outcome, target = ('merge' if event_home(conn, successor_of, store.view_key(conn, successor_of), c) else 'succession'), successor_of
        peers = collision_peers(conn, c, listed) if getattr(cfg, 'collision', None) else []
        judged = ''
        if peers:
            answer, verdicts = ask_collision_judge(archive, cfg, conn, candidate_state(c, evidence), peers, llm_transport)
            total.cost_usd += answer.cost_usd
            total.input_tokens += answer.input_tokens
            total.output_tokens += answer.output_tokens
            total.calls += 1
            total.cached = total.cached and answer.cached
            shas.append(answer.request_sha256)
            total.request_records.append({'call_id': answer.call_id, 'request_sha256': answer.request_sha256})
            judged = '; collision judge: ' + ', '.join(f'{v}: {verdicts.get(v, "(no answer)")}' for v in peers)
            if target in peers and verdicts.get(target) not in ('same_question', 'same_question_other_period'):
                outcome, target = 'new', ''                      # Jev's merge or succession on a peer the judge keeps apart
            if outcome == 'new':
                for v in peers:
                    key = store.view_key(conn, v)
                    if verdicts.get(v) == 'same_question' and not identity.conflicts(key, c, merging=False):
                        if identity.conflicts(key, c, merging=True):
                            if can_succeed(conn, v, key, c):
                                outcome, target = 'succession', v
                                break
                            continue
                        if store.is_open(conn, v):
                            outcome, target = 'merge', v
                            break
                    if verdicts.get(v) == 'same_question_other_period' and can_succeed(conn, v, key, c):
                        outcome, target = 'succession', v
                        break
        data['candidates'].append({'id': c['id'], 'outcome': outcome, 'target_view_id': target or '', 'dependencies': [],
                                   'reason': f'jev: {reasons or "no list"}; groups joined: {joined or "none"}{judged}'})
    for e, pairs, said_day, job_index in evidence_jobs:
        answers = answers_for(job_index)
        for _, v in pairs:
            scored = [(answers[f'piece__{v}__{x}'], x) for x in lists.evidence_lists[(e['id'], v)]]
            repeats = sorted(((a['probabilities']['same_statement'], x) for a, x in scored if a['choice'] == 'same_statement' and a['probabilities']['same_statement'] >= THRESHOLD), reverse=True)
            replaces = sorted(((a['probabilities']['supersedes'], x) for a, x in scored if a['choice'] == 'supersedes' and a['probabilities']['supersedes'] >= THRESHOLD), reverse=True)
            outcome, target = ('repeat', repeats[0][1]) if repeats else ('replace', replaces[0][1]) if replaces else ('new', '')
            data['evidence'].append({'id': e['id'], 'view_id': v, 'outcome': outcome, 'target_evidence_id': target or '', 'said_day': said_day,
                                     'reason': 'jev: ' + '; '.join(f'{x}: {_summary(a)}' for a, x in scored)})
    total.request_sha256 = hashlib.sha256('+'.join(shas).encode('utf-8')).hexdigest() if shas else ''
    return total

"""Step 2 outcome and forward-order contract (PRD §5; Alex 2026-11-08: a record matching several groups joins only the one it is most
like); Jev and the embeddings are fakes, the Step 3 library is real."""
import importlib.util
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


compare = load('clean_step2_compare', HERE / 'compare.py')
library = load('clean_step3_library', HERE.parent / 'step3/library.py')


def answer(choice, same_probability):
    rest = (1 - same_probability) / 2
    return {'choice': choice, 'probabilities': {'same_statement': same_probability, 'supersedes': rest, 'different': rest}}


def record(record_id, article, summary, party='NVIDIA'):
    return {'id': record_id, 'article': article, 'publisher': 'Reuters', 'publication_date': '2026-07-06', 'summary': summary,
            'passages': [summary], 'original_party': party, 'reporting_speaker': 'Reuters', 'tier': 'party_statement',
            'statement_date': '2026-07-06', 'evidence_period': None, 'thesis_ids': ['clean-1']}


class OutcomeTest(unittest.TestCase):
    def test_several_repeats_join_only_the_most_likely_group(self):
        result = compare.outcome({'1:e1': answer('same_statement', 0.62), '2:e1': answer('same_statement', 0.91),
                                  '3:e1': answer('different', 0.05)}, ['1:e1', '2:e1', '3:e1'])
        self.assertEqual(result, {'kind': 'repeat', 'repeat_of': ['2:e1'], 'revises': []})

    def test_equal_probabilities_go_to_the_earliest_group(self):
        result = compare.outcome({'2:e1': answer('same_statement', 0.8), '1:e1': answer('same_statement', 0.8)}, ['1:e1', '2:e1'])
        self.assertEqual(result['repeat_of'], ['1:e1'])

    def test_repeat_with_a_supersedes_answer_elsewhere_keeps_the_revision_link(self):
        result = compare.outcome({'1:e1': answer('same_statement', 0.9), '2:e1': answer('supersedes', 0.1)}, ['1:e1', '2:e1'])
        self.assertEqual(result, {'kind': 'repeat', 'repeat_of': ['1:e1'], 'revises': ['2:e1']})

    def test_supersedes_without_a_repeat_is_a_revision_and_no_match_is_new(self):
        self.assertEqual(compare.outcome({'1:e1': answer('supersedes', 0.1)}, ['1:e1']), {'kind': 'revision', 'revises': ['1:e1']})
        self.assertEqual(compare.outcome({'1:e1': answer('different', 0.1)}, ['1:e1']), {'kind': 'new'})


class ForwardTest(unittest.TestCase):
    def test_a_later_article_joins_the_group_and_records_of_one_article_never_see_each_other(self):
        guidance = record('1:e1', 1, 'NVIDIA guided Q2 revenue to about $91 billion.')
        same_article = record('1:e2', 1, 'NVIDIA guided Q2 revenue to about $91 billion, plus or minus 2%.')
        retelling = record('2:e1', 2, 'NVIDIA guided Q2 revenue to $91 billion and assumes no China data-centre revenue.')
        texts = [compare.doc_text(r) for r in (guidance, same_article, retelling)] + \
                [compare.query_text(r, 'Will data-centre revenue grow?') for r in (guidance, same_article, retelling)]
        vectors = {text: [1.0, 0.0] for text in texts}
        asked = []
        def ask(state, questions):
            asked.append((state, len(questions)))
            return {q: answer('same_statement', 0.9) for q in questions}
        store = library.Library()
        decisions = compare.forward([[guidance, same_article], [retelling]], store, vectors, {'clean-1': 'Will data-centre revenue grow?'}, ask)
        self.assertEqual(store.order, ['1:e1', '1:e2'])
        self.assertEqual([m['id'] for m in store.groups['1:e1']['members']], ['2:e1'])
        self.assertEqual(len(asked), 1)
        self.assertEqual(decisions[2]['outcome'], {'kind': 'repeat', 'repeat_of': ['1:e1'], 'revises': []})

