        early = dict(record('1:e1', 1, 'Dell is bringing the RTX Spark chip to its XPS laptops.'), thesis_ids=[])
        opener = dict(record('2:e1', 2, 'Microsoft launched a laptop with the RTX Spark chip.'), thesis_ids=['rtx-spark'])
